  var MOTORES_FORA = /^(stur|mpeg)$/i

  function aplicarRegras() {
    // Cards de filme/serie: a midia (div clicavel) vira foco do D-pad.
    // Sem isto o D-pad so acha o coracao e os 3 pontos dentro do card.
    document.querySelectorAll('.poster-media').forEach(function (el) {
      if (el.dataset.tvFocus !== '1') { el.dataset.tvFocus = '1'; el.tabIndex = 0 }
    })
    // Rail: Downloads
    document.querySelectorAll('.home-rail-btn').forEach(function (b) {
      if (/^downloads/i.test(texto(b))) esconder(b)
    })
    // Abas de configuracao que nao fazem sentido na TV
    document.querySelectorAll('.settings-page-nav-btn').forEach(function (b) {
      if (ABAS_FORA.test(texto(b))) esconder(b)
    })
    // Motores de video que nao existem no Tizen (STUR = mpv do .exe, MPEG = remux)
    document.querySelectorAll('.player-engine-card').forEach(function (b) {
      var nome = b.querySelector('strong')
      if (nome && MOTORES_FORA.test(texto(nome))) esconder(b)
    })
    // Botoes de baixar (VOD)
    document.querySelectorAll('button').forEach(function (b) {
      var t = texto(b)
      if (/^(baixar|download|baixando|pausar download)/i.test(t)) esconder(b)
    })
    // "Controles ao mover o mouse" e afins
    if (!window.__tvMouseOculto) {
      var labels = document.querySelectorAll('label, .settings-row, .settings-block')
      for (var i = 0; i < labels.length; i++) {
        var t = texto(labels[i])
        if (/controles? ao mover|user-agent personalizado/i.test(t) && t.length < 160) {
          esconder(labels[i])
          window.__tvMouseOculto = true
          break
        }
      }
    }
  }

  var agendado = false
  function agendar() {
    if (agendado) return
    agendado = true
    requestAnimationFrame(function () {
      agendado = false
      try { aplicarRegras() } catch (e) {}
    })
  }

  /* ------------------------------------------------------- navegacao por D-pad */
  var FOCO = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"]), [data-tv-focus="1"]'

  function focaveis() {
    var todos = document.querySelectorAll(FOCO)
    var out = []
    for (var i = 0; i < todos.length; i++) {
      var el = todos[i]
      if (el.disabled || el.getAttribute('aria-hidden') === 'true') continue
      if (el.dataset.tvOculto === '1') continue
      if (!visivel(el)) continue
      out.push(el)
    }
    return out
  }

  function caixa(el) {
    var r = el.getBoundingClientRect()
    return { x: r.left + r.width / 2, y: r.top + r.height / 2, w: r.width, h: r.height }
  }

  function focado() {
    var a = document.activeElement
    if (!a || a === document.body || a === document.documentElement) return null
    if (!visivel(a)) return null
    return a
  }

  function proximo(dir) {
    var lista = focaveis()
    if (!lista.length) return null
    var atual = focado()
    if (!atual || lista.indexOf(atual) === -1) return lista[0]

    var a = caixa(atual)
    var melhor = null
    var melhorScore = Infinity
    for (var i = 0; i < lista.length; i++) {
      var el = lista[i]
      if (el === atual) continue
      var b = caixa(el)
      var dx = b.x - a.x
      var dy = b.y - a.y
      var ok = dir === 'left' ? dx < -2 : dir === 'right' ? dx > 2 : dir === 'up' ? dy < -2 : dy > 2
      if (!ok) continue
      var principal = (dir === 'left' || dir === 'right') ? Math.abs(dx) : Math.abs(dy)
      var ortogonal = (dir === 'left' || dir === 'right') ? Math.abs(dy) : Math.abs(dx)
      // Penaliza muito elementos fora do eixo atual
      var limite = (dir === 'left' || dir === 'right') ? (a.h + b.h) / 2 : (a.w + b.w) / 2
      var extra = ortogonal > limite ? ortogonal * 5 : ortogonal * 2
      var score = principal + extra
      if (score < melhorScore) { melhorScore = score; melhor = el }
    }
    return melhor
  }

  function ehCampo(el) {
    if (!el) return false
    var tag = el.tagName
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable
  }

  function noPlayer() {
    return document.body.classList.contains('player-active')
  }

