  var navegando = false

  function secaoAtiva() {
    var b = document.querySelector('.home-rail-btn.active')
    if (!b) return ''
    return texto(b).replace(/\s*\(.*\)\s*$/, '').trim()
  }

  function irParaSecao(nome) {
    var botoes = document.querySelectorAll('.home-rail-btn')
    for (var i = 0; i < botoes.length; i++) {
      var t = texto(botoes[i]).replace(/\s*\(.*\)\s*$/, '').trim()
      if (t.toLowerCase() === String(nome || '').toLowerCase()) {
        navegando = true
        botoes[i].click()
        setTimeout(function () { navegando = false }, 900)
        return true
      }
    }
    return false
  }

  setInterval(function () {
    if (navegando) return
    var s = secaoAtiva()
    if (!s || s === secaoAtual) return
    pilhaSecoes.push(secaoAtual)
    if (pilhaSecoes.length > 30) pilhaSecoes.shift()
    secaoAtual = s
  }, 700)

  function sairApp() {
    try {
      if (window.tizen && window.tizen.application) {
        window.tizen.application.getCurrentApplication().exit()
        return
      }
    } catch (e) {}
    try { window.close() } catch (e) {}
  }

  function mostrarSaida() {
    if (document.getElementById('tv-exit')) return
    var wrap = document.createElement('div')
    wrap.id = 'tv-exit'
    wrap.style.cssText = 'position:fixed;inset:0;z-index:2147483647;background:rgba(0,0,0,.78);display:flex;align-items:center;justify-content:center;'
    var box = document.createElement('div')
    box.style.cssText = 'background:#0b0f16;border:2px solid #2a3446;border-radius:16px;padding:44px 60px;min-width:560px;text-align:center;color:#fff;font:600 22px/1.3 sans-serif;box-shadow:0 24px 70px rgba(0,0,0,.65)'
    var titulo = document.createElement('p')
    titulo.textContent = 'Deseja sair do ST PLAY?'
    titulo.style.cssText = 'margin:0 0 30px'
    var row = document.createElement('div')
    row.style.cssText = 'display:flex;gap:22px;justify-content:center'
    var sim = document.createElement('button')
    sim.textContent = 'Sair'
    sim.style.cssText = 'min-width:180px;padding:18px 26px;border-radius:10px;border:0;background:#e11d48;color:#fff;font:700 20px sans-serif;cursor:pointer'
    var nao = document.createElement('button')
    nao.textContent = 'Cancelar'
    nao.style.cssText = 'min-width:180px;padding:18px 26px;border-radius:10px;border:2px solid #3b4658;background:transparent;color:#fff;font:700 20px sans-serif;cursor:pointer'
    var anterior = document.activeElement
    sim.onclick = sairApp
    nao.onclick = function () {
      wrap.remove()
      try { if (anterior && anterior.focus) anterior.focus() } catch (e) {}
    }
    row.appendChild(sim)
    row.appendChild(nao)
    box.appendChild(titulo)
    box.appendChild(row)
    wrap.appendChild(box)
    document.body.appendChild(wrap)
    setTimeout(function () { try { sim.focus() } catch (e) {} }, 60)
  }

  function voltar() {
    // dialogo de saida aberto: fecha
    var dialogo = document.getElementById('tv-exit')
    if (dialogo) { dialogo.remove(); return }
    // player aberto: o app fecha com Escape
    if (noPlayer()) { dispararEscape(); return }
    // Voltar escondido do app (ficha/player) - continua clicavel
    var bv = document.querySelector('button[title="Voltar"], .series-back-btn, .player-back-always')
    if (bv) { try { bv.click(); return } catch (e) {} }
    // tela com botao de voltar/fechar
    var botoes = document.querySelectorAll('button')
    for (var i = 0; i < botoes.length; i++) {
      var b = botoes[i]
      if (!visivel(b)) continue
      if (/^(voltar|voltar ao|fechar|close|cancelar)$/i.test(texto(b))) { b.click(); return }
    }
    // de qualquer aba/categoria: volta pro menu (Inicio)
    if (secaoAtual && secaoAtual !== 'In\u00edcio') {
      if (irParaSecao('In\u00edcio')) { secaoAtual = 'In\u00edcio'; return }
    }    // inicio: oferece sair
    mostrarSaida()
  }

  function dispararEscape() {
    var ev = new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true })
    document.dispatchEvent(ev)
    window.dispatchEvent(ev)
  }

  function clicar(el) {
    if (!el) return
    if (typeof el.click === 'function') el.click()
    else el.dispatchEvent(new MouseEvent('click', { bubbles: true }))
  }

  document.addEventListener('focusin', function (e) {
    var el = e.target
    if (!el || !el.closest) return
    // hover sintetico para prewarm/estado de hover
    try { el.dispatchEvent(new MouseEvent('mouseover', { bubbles: true, cancelable: true, view: window })) } catch (err) {}
    var row = el.closest('.live-channel-row')
    if (row) {
      clearTimeout(window.__tvPreviewTimer)
      window.__tvPreviewTimer = setTimeout(function () {
        var btn = row.querySelector('button.channel')
        if (btn) { try { btn.click() } catch (err) {} }
      }, 350)
    }
  }, true)

  document.addEventListener('keydown', function (e) {
    var alvo = e.target
    var campo = ehCampo(alvo)
    var key = e.key || ''

    if (av) {
      if (key === 'ArrowLeft') { e.preventDefault(); e.stopPropagation(); avSeek(-10000); return }
      if (key === 'ArrowRight') { e.preventDefault(); e.stopPropagation(); avSeek(10000); return }
      if (key === 'ArrowUp' || key === 'ArrowDown') { e.preventDefault(); e.stopPropagation(); avMostrarBarra(); return }
      if (key === 'Enter' || key === ' ') { e.preventDefault(); e.stopPropagation(); avToggle(); return }
      if (e.keyCode === 10009 || key === 'GoBack' || key === 'BrowserBack') { e.preventDefault(); e.stopPropagation(); avFechar(true); return }
      avMostrarBarra()
      return
    }

    if (key === 'ArrowLeft' || key === 'ArrowRight' || key === 'ArrowUp' || key === 'ArrowDown') {
      if (campo && (key === 'ArrowLeft' || key === 'ArrowRight')) return
      var el = proximo(key.replace('Arrow', '').toLowerCase())
      if (el) {
        e.preventDefault()
        e.stopPropagation()
        el.focus()
        try { el.scrollIntoView({ block: 'nearest', inline: 'nearest' }) } catch (err) { el.scrollIntoView() }
      }
      return
    }

    if (key === 'Enter' || key === ' ') {
      if (campo) return
      var at = focado()
      if (!at) return
      var row = at.closest ? at.closest('.live-channel-row') : null
      if (row) {
        var fs = document.querySelector('.live-preview-panel button[title*="Tela Cheia"], .live-preview-panel button[aria-label*="Tela Cheia"]')
        if (!fs) {
          var bts = document.querySelectorAll('.live-preview-panel button')
          for (var bi = 0; bi < bts.length; bi++) {
            var bt = (bts[bi].getAttribute('title') || bts[bi].getAttribute('aria-label') || bts[bi].innerText || '')
            if (/tela cheia/i.test(bt)) { fs = bts[bi]; break }
          }
        }
        if (fs) { e.preventDefault(); e.stopPropagation(); clicar(fs); return }
      }
      e.preventDefault()
      e.stopPropagation()
      clicar(at)
      return
    }

    // Tizen: 10009 = voltar; GoBack em alguns controles
    if (e.keyCode === 10009 || key === 'GoBack' || key === 'BrowserBack') {
      e.preventDefault()
      e.stopPropagation()
      voltar()
      return
    }

    // Teclas de midia do controle
    if (key === 'MediaPlayPause') {
      var play = document.querySelector('.player-active button[aria-label*="ausar"], .player-active button[title*="ausar"], .player-active button[aria-label*="eproduzir"], .player-active button[title*="eproduzir"]')
      if (play) { e.preventDefault(); clicar(play) }
      return
    }
  }, true)

